import { spawn } from 'node:child_process'
import { tmpdir } from 'node:os'
import path from 'node:path'
import fs from 'node:fs'

import type { Spec } from '../resource.ts'

export interface Config {
  bin?: string
  /** Additional environment variables */
  env?: Record<string, string>
  /** Default arguments to pass to the command */
  defaultArgs?: string[]
  /** Program arguments */
  argv?: string[]
  /** Default stack when not named */
  default?: string
  /** Docker compose stacks */
  stacks: Record<string, Stack>
}

type Stack = Spec | (() => Promise<Spec>) | Promise<Spec> | string

export const define = (config: Config): Config => config

export const cli = async (config: Config) => {
  const ctx = createContext(config)
  const args = config.argv ?? process.argv.slice(2)

  const stackNames = Object.keys(config.stacks)

  if (args.length === 0) throw new Error('Help not yet implemented')

  let stackName = args.length > 0 && config.stacks[args[0]!] ? (args.shift(), args[0]) : config.default
  if (!stackName && stackNames.length === 1) stackName = stackNames[0]
  if (!stackName || !config.stacks[stackName]) throw new Error(`Stack ${stackName} not found`)

  const cmd = commands[args[0] as keyof typeof commands]!
  if (cmd) {
    args.shift()
    throw new Error(`Command ${cmd} not yet implemented`)
  }

  const file = await resolvePath(ctx, config.stacks[stackName]!)
  return execute(ctx, {
    bin: ctx.config.bin ?? 'docker',
    env: { ...process.env, ...(ctx.config.env ?? {}) },
    args: [...(ctx.config.defaultArgs ?? ['compose']), '-f', file, ...(ctx.config.argv ?? process.argv.slice(2))],
  })
}

type Context = { config: Config; temp: string }
const createContext = (config: Config): Context => ({ config, temp: fs.mkdtempSync(path.join(tmpdir(), 'ship-')) })

const resolvePath = async (ctx: Context, stack: Stack): Promise<string> => {
  if (typeof stack === 'string') return stack
  if (typeof stack === 'function') return storeScratch(ctx, stack())
  return storeScratch(ctx, stack)
}

const storeScratch = async (ctx: Context, stack: Promise<Spec> | Spec) => {
  const st = await stack
  const scratch = path.join(ctx.temp, `${st.name}.json`)
  await fs.promises.writeFile(scratch, JSON.stringify(st, null, 2))
  return scratch
}

type ShellOptions = { bin: string; env: Record<string, string | undefined>; args: string[] }
const execute = (ctx: Context, config: ShellOptions): Promise<number> => {
  return new Promise<number>((done, fail) => {
    const child = spawn(config.bin, config.args, { stdio: 'inherit', env: config.env })
    child.on('error', fail)
    child.on('close', (code, signal) => done(code ?? (signal ? 1 : 0)))
  }).finally(() => cleanScratch(ctx))
}

const cleanScratch = (ctx: Context) => {
  for (const file of fs.readdirSync(ctx.temp)) {
    fs.rmSync(path.join(ctx.temp, file), { recursive: true, force: true })
  }
}

